import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { DemoCard } from '../components/DemoCard';
import { personas } from '../personas';
// Everything below is generated by Orval from server/openapi.yaml (npm run api:gen -w client).
import { getProduct, listProducts, useListProducts } from '../api/generated/endpoints/products/products';
import { getUser } from '../api/generated/endpoints/users/users';
import {
  createOrder,
  getListOrdersQueryKey,
  listOrders,
  useCreateOrder,
  useListOrders,
} from '../api/generated/endpoints/orders/orders';
import type { CreateOrderRequest } from '../api/generated/model';

const CATEGORIES = ['all', 'peripherals', 'displays', 'audio', 'furniture', 'video'] as const;

export function MockApi() {
  return (
    <div className="page">
      <h1>Mock API</h1>
      <p className="lead">
        Successful requests to the Express mock backend. Every click is a trace: the browser span, the{' '}
        <code>http.client</code> fetch span, and the server's own spans, including simulated DB queries. Requests use
        typed functions and TanStack Query hooks that Orval generates from <code>server/openapi.yaml</code>.
      </p>

      <QueryHooksDemo />

      <div className="grid">
        <DemoCard
          title="List products"
          description={<code>GET /api/products</code>}
          lookFor="Traces → the trace for this click: frontend ui.action → fetch → backend GET /api/products → db.sql.query span."
          actions={[
            { label: 'All products', tone: 'success', run: () => listProducts() },
            { label: 'Peripherals only', tone: 'success', run: () => listProducts({ category: 'peripherals' }) },
          ]}
        />

        <DemoCard
          title="Fetch a user"
          description={<code>GET /api/users/:id</code>}
          lookFor="The backend span carries the user id from the x-demo-user header (if you picked a persona)."
          actions={personas.map((p) => ({
            label: p.name,
            tone: 'success' as const,
            run: () => getUser(p.id),
          }))}
        />

        <DemoCard
          title="Create an order"
          description={<code>POST /api/orders</code>}
          lookFor="Logs → an 'Order created' log line with orderId and total attributes, linked to the trace."
          actions={[
            {
              label: 'Place valid order',
              tone: 'success',
              run: () =>
                createOrder({ userId: 'u_1002', items: [{ productId: 1, quantity: 1 }, { productId: 6, quantity: 2 }] }),
            },
            { label: 'List orders', tone: 'success', run: () => listOrders() },
          ]}
        />

        <DemoCard
          title="Expected client errors (4xx)"
          description="A 404 and a 400 validation failure. The backend logs them but doesn't create backend issues for them."
          lookFor="The card reports these from the frontend, so you get a frontend issue with the response body as context, a backend log line, and no backend issue: 4xx is noise on the server."
          actions={[
            { label: '404 product', tone: 'warning', run: () => getProduct(999) },
            {
              label: '400 bad order',
              tone: 'warning',
              // Deliberately invalid: the cast gets past the generated types so the server can reject it.
              run: () => createOrder({ items: [{ productId: 42, quantity: 0 }] } as unknown as CreateOrderRequest),
            },
          ]}
        />
      </div>
    </div>
  );
}

/** Shows the generated hooks themselves: cached queries per param, a mutation, and invalidation. */
function QueryHooksDemo() {
  const queryClient = useQueryClient();
  const [category, setCategory] = useState<(typeof CATEGORIES)[number]>('all');

  // Query key is ['/api/products', { category }], so each category is its own cache entry.
  const products = useListProducts(category === 'all' ? undefined : { category });
  const orders = useListOrders();
  const placeOrder = useCreateOrder({
    mutation: {
      onSuccess: () => queryClient.invalidateQueries({ queryKey: getListOrdersQueryKey() }),
    },
  });

  return (
    <section className="card query-demo">
      <header>
        <h3>Orval + TanStack Query</h3>
        <p className="muted">
          <code>useListProducts</code>, <code>useListOrders</code> and <code>useCreateOrder</code> are generated hooks.
          Open the React Query devtools (bottom-right) to watch the cache.
        </p>
      </header>

      <div className="query-demo-cols">
        <div>
          <label className="field">
            Category
            <select value={category} onChange={(e) => setCategory(e.target.value as typeof category)}>
              {CATEGORIES.map((c) => (
                <option key={c}>{c}</option>
              ))}
            </select>
          </label>
          {products.isPending ? (
            <p className="muted small">Loading…</p>
          ) : products.isError ? (
            <p className="small">Error {products.error.status}: {products.error.message}</p>
          ) : (
            <table className="data-table">
              <thead>
                <tr>
                  <th>Product</th>
                  <th>Price</th>
                  <th>Stock</th>
                  <th />
                </tr>
              </thead>
              <tbody>
                {products.data.data.map((p) => (
                  <tr key={p.id}>
                    <td>{p.name}</td>
                    <td>${p.price.toFixed(2)}</td>
                    <td>{p.stock}</td>
                    <td>
                      <button
                        className="btn btn-success btn-small"
                        disabled={placeOrder.isPending || p.stock === 0}
                        onClick={() => placeOrder.mutate({ data: { userId: 'u_1001', items: [{ productId: p.id, quantity: 1 }] } })}
                      >
                        Order
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
          {products.isFetching && !products.isPending && <p className="muted small">Refreshing…</p>}
        </div>

        <div>
          <p className="small">
            <strong>Orders</strong> {orders.data && <span className="muted">({orders.data.count})</span>}
          </p>
          {orders.isPending ? (
            <p className="muted small">Loading…</p>
          ) : orders.isError ? (
            <p className="small">Error {orders.error.status}: {orders.error.message}</p>
          ) : (
            <table className="data-table">
              <thead>
                <tr>
                  <th>Order</th>
                  <th>User</th>
                  <th>Total</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {orders.data.data.map((o) => (
                  <tr key={o.id}>
                    <td>#{o.id}</td>
                    <td>{o.userId}</td>
                    <td>${o.total.toFixed(2)}</td>
                    <td>{o.status}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
          {placeOrder.isError && <p className="small">Order failed: {placeOrder.error.message}</p>}
          {placeOrder.isSuccess && <p className="muted small">Created order #{placeOrder.data.data.id}; list refetched.</p>}
        </div>
      </div>
    </section>
  );
}
